// Renders configuration assignments from one canonical task record. Does not approve content reviews.
const fs=require('fs'),path=require('path');
const root=path.resolve(__dirname,'..');
const dir=path.join(root,'docs/phase 2/ppap/solution_specification');
const model=JSON.parse(fs.readFileSync(path.join(dir,'ppap-target-model.json'),'utf8'));
const objects=new Map(model.objects.map(o=>[o.id,o]));
const fieldMap=new Map();
const tasks=[];
const externalInputs=[
 ['IN-01','Client PPAP library and procedure','The client has been asked for the controlled SIA PPAP spreadsheet, procedure, IntelliQuest requirements/questions and template/classification matrix. They have not yet been supplied. Their exact content, protection rules, routing, dates and approved category/phase/stage/exception values are needed to complete the affected configuration; Objects and known controls can proceed.'],
 ['IN-02','Operational engineering data and record links','SIA and the operational Product Management owner must supply the separate BOMEX/ECS delivery contract, producer/event/revision keys, drawing and part object/field identifiers, facility/depot crosswalks, explicit classification authority/precedence, full/delta/correction/removal rules, source ordering, accepted release criteria and external endpoint/credentials. Source selectors, receipt and correction processing wait for these exact values; the isolated Product Integration application is not that connection.'],
 ['IN-03','Supported target workflow and shared-handler connection','The technical team must supply the supported way to select a new PPAP-only workflow for target records, read the PPAP-only Target Configuration? field from shared handlers, set it before legacy handlers run, and resolve the direct/inherited Id name collision. The plan assigns the resulting configuration changes, not a tenant-verification exercise.'],
 ['IN-04','Supported complete-save, copy and recovery methods','The technical team must supply the supported native methods for saving related records/files together, preventing conflicting simultaneous changes, retaining action/audit reasons, reopening an approved element without losing history, and durably resuming failed publication/submission/cancellation/outcome delivery. Only the consuming operations wait; no processing-permission or custom audit subsystem is requested.'],
 ['IN-05','Approved SIA roles, supplier roles and capability rules','The SRM/security owners must supply the governed library-role and exact-entity role identifiers, populated memberships, SIA engineer selections, inspection teams/leaders, management approver pool and PPAP administrator group. They must also supply central ACTIVE/SERVICE/INACTIVE capability identifiers and reconcile the annotated central open-work transition rule. These are existing shared authorities; membership administration and central policy decisions are outside the build assignments.'],
 ['IN-06','Record visibility, file access and supplier actor connection','The security/technical team must supply visibility classification values and access rules, native record/file/API/export enforcement methods, authorized handover principals, and the supported external-supplier-user to native actor/recipient identity connection. This information limits the affected security, posting, confirmation and recorded-actor settings.'],
 ['IN-07','Released inspection specifications and result evidence','The Product Management/Inspection owners must supply released-specification and result object/field identifiers, valid released states and scope keys, and an immutable result-version reference or controlled result-artifact export. Required review/result checks and links wait for those values; measurements and specification publishing remain external.'],
 ['IN-08','PCR and APQP launch and outcome connections','The PCR/APQP owners must supply the Proceed to PPAP decision token and fields, authorized launch/callback actions, originating owner-resolution destination, and the rule for obligations served by multiple linked PPAPs. Target launch and successful/cancelled outcomes wait for those connections; no new MOC/PCR lifecycle is assigned.'],
 ['IN-09','New-model pilot launch connection','The Pilot Part Data owner must supply the program launch operation, identifiers and PPAP/model/build-event/part mappings, including retry correlation. The PPAP launch link waits; the pilot application and its shipments/measurements are outside this plan.'],
 ['IN-10','Business timezone and native notice scheduling','SIA must supply its business timezone. The technical team must supply the native reminder/delivery settings for the proposed daily 08:00 scan, repeat prevention, retry and access checks at delivery. Calendar-day values are known; the timezone and native connection cannot be inferred from the workstation.'],
 ['IN-11','Approval certificate and authorized verification route','SIA must supply the approved certificate layout and required supplier/facility identity labels. The technical team must supply native PDF generation, saved-file/opaque-reference handling, authenticated verification route and native display-field sources for frozen approval labels. Optional QR rendering does not block the ordinary PDF.'],
 ['IN-12','Report source fields and reporting periods','The technical team must supply native workflow/history/audit/report field identifiers and supported report/query methods. SIA must agree the materially-overdue report threshold and reporting-period/cohort boundaries for historical supplier timeliness. Any later scorecard attribution/query connection is supplied by the scorecard owner; scoring configuration and published-scorecard updates are not PPAP tasks.'],
 ['IN-13','Supported attachment limits and file controls','The tenant administrator must supply supported file sizes/types and the native method that protects posted/submitted files from editing or deletion. Average files are 1 MB, not an upload maximum. Ordinary attachments need no specialist viewer.'],
 ['IN-14','Target screens and supported expressions','The technical team must supply supported expressions and view-action methods where this design states business logic rather than executable Intelex syntax, together with the effective tenant view/module identifiers if they differ from the package. Build assignments use the verified package names and must not guess a replacement expression or tenant target.']
].map(([id,title,description])=>({id,title,description}));
const inputById=new Map(externalInputs.map(x=>[x.id,x]));
const defaults={implementer:'Senior Consultant',reviewer:'Senior Consultant — PPAP build reviewer (a different person)',rationale:'This work changes several related records or decisions. A Senior Consultant should configure its order and recovery behavior because an incomplete update could change approval history or expose the wrong work.',assumptions:'New operational PPAPs only. SIA PPAP Engineer means an internal SIA user; supplier personnel act through their separate supplier roles.'};
function task(n,title,category,objective,scope,deliverable,prereqs=[],inputs=[],extra={}){
 const t={id:'IMP-'+String(n).padStart(2,'0'),title,category,objective,scope,deliverable,prerequisites:prereqs.map(x=>'IMP-'+String(x).padStart(2,'0')),predecessorOutputs:[],inputs:inputs.map(x=>Array.isArray(x)?x[0]:x),suppliedInputDescriptions:inputs.map(x=>({id:x[0],description:x[1]})),configurationRows:[],modifications:[],steps:[],accept:[],refs:['[Target PPAP technical specification](ppap-target-technical-specification.md)','[Canonical target field contract](ppap-target-field-contract.md)'],blockedStatus:inputs.length?'Partly waiting: the task-local information below is needed for the named settings.':'Ready: no external information is missing; the earlier configuration outputs listed below are still required.',...defaults,...extra};tasks.push(t);return t;
}
const setupRole={implementer:'Senior Associate Consultant',rationale:'The assignment combines established field, related-list and form settings. A Senior Associate Consultant can apply the conditions consistently, with the separate build reviewer checking their effect on the wider process.'};
const ordinaryRole={implementer:'Associate Consultant',rationale:'The record/list settings and known starting values follow an established pattern. An Associate Consultant can build them while a separate Senior Consultant reviews conditional behavior and supplied values.'};
const connectionRole={implementer:'Consultant',rationale:'The assignment connects defined records and actions through supplied native methods. A Consultant should configure the cross-record checks and failure messages; it does not assign the external application build.'};
const protectedNames=[...new Set(['SIA PPAP Engineer','Engineer Review','Engineering Review','Management Review','Work In Progress','In Progress',...model.objects.map(o=>o.name),...model.objects.flatMap(o=>o.fields.map(f=>f.name))])].sort((a,b)=>b.length-a.length);
function business(s){const saved=[];let text=String(s);for(const n of protectedNames)text=text.split(n).join('§'+saved.push(n)+'§');text=text.replace(/\bPPAP-(?:SCHEDULE|SCOPE|RELEASE|APPROVAL|[A-Z]+)-\d{3}\b/g,'the agreed PPAP rule').replace(/\bSystem read only\b/g,'Users cannot edit this value directly').replace(/\bSystem read-only\b/g,'Users cannot edit this value directly').replace(/\bSystem populated\b/g,'The named action fills this value').replace(/\bEngineer\b/g,'SIA PPAP Engineer').replace(/\bengineer\b/g,'SIA PPAP Engineer').replace(/\bidempotent\b/gi,'safe to run again without duplicates').replace(/\ban immutable\b/gi,'a fixed').replace(/\bimmutable\b/gi,'fixed').replace(/\bsame logical transaction\b/gi,'same successful save').replace(/\bcanonical\b/g,'governed').replace(/\bnullable\b/gi,'may be empty').replace(/\bsnapshot\b/gi,'saved copy');return text.replace(/§(\d+)§/g,(_,i)=>saved[Number(i)-1]);}
// Actual configured display names are never changed by the wording helper.
function typeMeaning(f){
 if(f.relationship==='1:M')return `Create a read-only related-record list over ${objects.get(f.source).name}.${f.source_field}; one owning record can show many linked entries (inverse 1:M). Store no second link.`;
 if(f.relationship==='M:1')return `Create a link to ${objects.get(f.target).name}, selecting ${f.required==='Y'?'exactly one':'zero or one'} target record (M:1; many source records may select it). ${f.inverse?'Enable the reverse read-only list '+objects.get(f.target).name+'.'+f.inverse+'.':'Keep its inverse disabled.'}`;
 if(f.relationship==='M:N')return `Create the native multiple-selection link to ${objects.get(f.target).name} (M:N); inverse disabled. Use native link storage without a new Object.`;
 if(f.native)return 'Use the Intelex native attachment collection, retaining file identity, name, length and content type. Do not create a custom file table.';
 return 'Set the type to '+f.type.replace(/max (\d+) characters/g,'up to $1 characters').replace('Integer (Int32); whole number','a whole number (Integer/Int32)').replace('Float; finite','a finite number allowing decimals (Float)').replace('Yes/No (Boolean)','Yes/No (Boolean)').replace('Text;','Text;')+'.';
}
const reuseFields=new Set(['ppap.Id','ppap.Project Owner','ppap.Settings','ppap.Task','ppap.APQP Abstract','ppap.PPAP Completion Date']);
const existingModifyFields=new Set(['ppap.PPAP Due Date','ppap.DisplayField']);
function addFields(t,ids,namesFilter=null){
 for(const id of ids){const o=objects.get(id);for(const f of o.fields){if(namesFilter&&!namesFilter(f,o))continue;
  const key=id+'.'+f.name;if(f.relationship==='1:M')continue;
  if(fieldMap.has(key))throw Error('Duplicate field owner '+key);
  fieldMap.set(key,t.id);
  if(reuseFields.has(key)||existingModifyFields.has(key))continue;
  const required=f.required==='Y'?'Required.':f.required==='N'?'Optional.':'Required only in the conditions stated below; otherwise optional.';
  const edit=business(f.edit);const life=business(f.lifecycle);
  t.configurationRows.push([o.name+'.'+f.name,`${typeMeaning(f)} ${required} Initial value or continuing calculation: ${business(f.default)}. Who can use it and when: ${edit}. Field/control lifecycle: ${life}`]);
 }}
}

const t01=task(1,'Create the PPAP Objects and workflow stages','Object setup','Provide the Objects and stage names needed before related PPAP features can be configured.','Create the 25 new non-catalogue Objects and the separate target PPAP, element and drawing-review workflow stages. Add the target-record marker on the existing PPAP. These early outputs let later assignments create links in both directions without circular build dependencies.','New PPAP Objects, new stage/termination entries and the target-record marker.',[],[['IN-03','Supply the supported target-only workflow selection and stage setup method; new Objects and the marker can be created before the target creation connection is completed.']],{...setupRole,blockedStatus:'Partly waiting: Objects and the target marker can be created; selecting the separate workflow for new target records waits for the supported native method.'});
for(const o of model.objects.filter(o=>o.domain!=='external'&&o.domain!=='catalogue'&&o.id!=='ppap'))t01.configurationRows.push([o.name+' Object',`Create this concrete Object in the existing PPAP product area. Business inheritance: none. Enable native audit and security; set attachments ${o.fields.some(f=>f.native)?'enabled':'disabled unless native infrastructure requires otherwise'}. ${o.fields.some(f=>f.type.includes('localizable'))?'Enable object localization for its marked display/instruction fields; stable Codes remain untranslated.':''} ${['element','review'].includes(o.id)?'Enable its new native workflow.':'Do not add a separate custom workflow or status field.'} Purpose: ${o.purpose} New internal names and metadata identifiers are allocated through normal Intelex configuration, not copied from the logical design IDs.`]);
t01.configurationRows.push(['Target PPAP workflow','Create Draft, In Progress and Management Review stages; set initial stage=Draft. Create Approved as a completed termination and Cancelled as a cancelled termination. Keep historical PPAP/APQP workflow definitions unchanged. Add no Interim Approval, withdrawal or closed-package reopen action. Consequential actions and responsibility rules are added by their owning process assignments before the target creation path is connected.'],['PPAP Element workflow','Create Work In Progress and Engineer Review stages; set initial stage=Work In Progress. Create Approved as completed and Cancelled as cancelled termination entries. Excluded requirements have no operational workflow.'],['PPAP Drawing Review workflow','Create Engineering Review stage and set it as initial. Create Review Complete with completed termination type. Do not add an Exception stage for transport failures.']);
addFields(t01,['ppap'],f=>f.name==='Target Configuration?');
t01.steps=['Set Target Configuration? to FALSE for ordinary existing records and allow only the proposed target creation action to write TRUE when creating a new target PPAP. Prevent later manual/API/import changes to that marker.','Create workflow/stage identities without attaching the new process to historical PPAP or APQP records. The creation connection will consume these new identities after its remaining checks are configured.'];
t01.accept=['The 25 new non-catalogue Objects exist and no shared supplier, identity, inspection or APQP Object has been recreated.','A target workflow has only the named stages/terminations; historical PPAP/APQP instances still point to their existing workflow definitions.'];

const t02=task(2,'Set up PPAP reference lists and operating settings','Lists and settings','Give PPAP a consistent set of selections and known review/reminder defaults.','Create seven independent PPAP reference lists with their exact fields and known starting values, plus the Operating Policy fields and settings form. Load controlled SIA values only when supplied; require complete role/timezone connections before activating the default policy.','PPAP lists, known starting entries, and an operating-policy form with controlled defaults.',[1],[['IN-01','Supply the exact category, schedule phase, manufacturing stage and drawing-review exception records. Their list structures and the eleven known type/pattern/answer entries can proceed.'],['IN-05','Supply the administrator group, management pool and three internal engineer library-role references used by the policy. Group creation and membership administration are not assigned here.'],['IN-10','Supply the business timezone identifier for Operating Policy.Business Time Zone. The numeric defaults and form can proceed before that selection is made.']],{...ordinaryRole,blockedStatus:'Partly waiting: all list/policy fields and the eleven known list entries can proceed; controlled SIA entries and policy activation wait for the listed content, group/role references and timezone.'});
addFields(t02,[...model.objects.filter(o=>o.domain==='catalogue').map(o=>o.id),'policy']);
for(const o of model.objects.filter(o=>o.domain==='catalogue'))for(const r of o.initial_values)t02.configurationRows.push([o.name+' entry '+r.Code,`Create Code=${r.Code}, Name=${r.Name}, Active?=${r['Active?']}, Sort=${r.Sort}. Names are localizable; Codes never change after use.`]);
t02.configurationRows.push(['Default PPAP policy entry','Create Code=PPAP_DEFAULT. Set Reminder Lead Days=3, Overdue Reminder Interval Days=7, Escalation Overdue Days=7, Engineer Review Days=5 and Management Review Days=5. Set Drawing Review Days=14 and read only. Populate Business Time Zone, PPAP Administrators, Default Management Approver Pool, Model Engineer Role, Running Change Engineer Role and Process Change Engineer Role from their supplied governed records. Permit exactly one active default after required values are complete.']);
t02.steps=['Create each list as a concrete independent localizable Object with native audit/security; no abstract catalogue family is added. Provide one Code, Name, Active? and Sort control per list. Make Name localizable for future translations and keep Code untranslated; launch labels are English. Keep references to inactive entries readable and block new selections of them.','Enter only the supplied SIA category/phase/stage/exception values, one record per Code with its approved Name, Active? and Sort. Do not substitute the OOTB eighteen elements or five levels.','On the policy form require whole nonnegative lead/escalation/review days; require overdue interval at least 1. Lock the confirmed 14-day drawing-review value. Prevent activation with missing required references/timezone or a second active default.'];
t02.accept=['The known Codes NEW_MODEL, RUNNING_CHANGE, PROCESS_CHANGE; SUPPLIER, INTERNAL, INSPECTION, JOINT; TEXT, NUMBER, BOOLEAN and DATE are separate records with the exact labels/order in their rows.','Inactive list entries cannot be newly selected but historical references remain visible.','The default policy cannot activate without required groups, role references and timezone; drawing review remains fixed at 14 calendar days.'];

